 "content": "import csv
from decimal import Decimal
from pathlib import Path

FX_DIR = Path(__file__).resolve().parent / "fixtures" / "fx"


def load_rates(day):
    """Return {currency: Decimal rate against USD} for an ISO date (YYYY-MM-DD).

    Rates live in one CSV per month: fixtures/fx/usd-YYYY-MM.csv, one row per date.
    """
    with open(FX_DIR / f"usd-{day[:7]}.csv", newline="") as f:
        for row in csv.DictReader(f):
            if row.pop("Date") == day:
                return {code: Decimal(rate) for code, rate in row.items()}
    raise KeyError(f"no FX rates for {day}")
"
}

